import { z } from '@bk-dash/core-typescript/schema'
import { ConnectionMode, MarketingPlatform, StoreIntegrationType } from '@bk-dash/contracts-typescript/wire/enums'

/** Meta — OAUTH mode: user authorises via Meta; businessAccountId is the connect-form field. */
export const MetaOAuthDescriptionSchema = z.object({
	connectionMode: z.literal(ConnectionMode.OAUTH),
	type: z.literal(StoreIntegrationType.MARKETING_PLATFORM),
	platform: z.literal(MarketingPlatform.META),
	active: z.literal(true),
	scopes: z.tuple([z.literal('ads_read'), z.literal('business_management')]),
	inputTokens: z.object({}),
	outputTokens: z.object({ accessToken: z.string(), refreshToken: z.string(), scope: z.string() }),
})

/** Runtime scope list derived from the descriptor — single source for authorize URL. */
export const MetaOAuthScopes = MetaOAuthDescriptionSchema.shape.scopes.def.items.map(item => item.value) as readonly string[]

/** Meta — MANUAL mode: no API; field-mapping only. */
export const MetaManualDescriptionSchema = z.object({
	connectionMode: z.literal(ConnectionMode.MANUAL),
	type: z.literal(StoreIntegrationType.MARKETING_PLATFORM),
	platform: z.literal(MarketingPlatform.META),
	active: z.literal(true),
	scopes: z.tuple([]),
	inputTokens: z.object({}),
	outputTokens: z.object({}),
})

