/**
 * Normalize JSON-Schema `const` to the OpenAPI 3.0 single-value `enum` form.
 *
 * Zod's `toJSONSchema` emits `z.literal(x)` as `{ const: x }`, but `const` is a
 * JSON-Schema-2020 / OpenAPI-3.1 keyword — not valid 3.0 (which this spec is,
 * per preprocess R-01). More importantly, `@kubb/plugin-ts` renders a bare
 * `const` by widening to its base type (`string`/`boolean`), collapsing literal
 * discriminants to `string`; it renders a single-value `enum` as a TS literal.
 * Rewriting `{ const: x }` → `{ enum: [x] }` therefore (a) makes the spec valid
 * 3.0 and (b) restores literal types — which is what lets the frontend narrow a
 * discriminated union (e.g. PlatformRegistrySchema's connectionMode/type/platform).
 * TS-only: Go's oapi-codegen has its own const handling, left untouched.
 */
function constToEnum(node: unknown): void {
	if (!node || typeof node !== 'object') return
	if (Array.isArray(node)) {
		for (const child of node) constToEnum(child)
		return
	}
	const obj = node as Record<string, unknown>
	if ('const' in obj && !('enum' in obj)) {
		obj.enum = [obj.const]
		delete obj.const
	}
	for (const value of Object.values(obj)) constToEnum(value)
}

